42	class WorksPageDomRuntime {
43	  private readonly _root: ParentNode;
44	
45	  constructor(root: ParentNode) {
46	    this._root = root;
47	  }
48	
49	  resolve(): WorksPageElements {
50	    return {
51	      root: this._queryElement<HTMLElement>(WORK_PAGE_DOM.rootSelector),
52	      canvas: this._queryCanvasElement(WORK_CANVAS_CONFIG.canvasId),
53	      grid: this._queryElement<HTMLElement>(WORK_PAGE_DOM.gridSelector),
54	      gridList: this._queryElement<HTMLUListElement>(
55	        WORK_PAGE_DOM.gridListSelector,
56	      ),
57	      gridPagination: this._queryElement<HTMLElement>(
58	        WORK_PAGE_DOM.gridPaginationSelector,
59	      ),
60	      controls: this._queryElement<HTMLElement>(WORK_PAGE_DOM.controlsSelector),
61	      toggle: this._queryElement<HTMLElement>(WORK_PAGE_DOM.toggleSelector),
62	      filterWrap: this._queryElement<HTMLElement>(
63	        WORK_PAGE_DOM.filterWrapSelector,
64	      ),
65	      filterButton: this._queryElement<HTMLButtonElement>(
66	        WORK_PAGE_DOM.filterButtonSelector,
67	      ),
68	      filterPanel: this._queryElement<HTMLElement>(
69	        WORK_PAGE_DOM.filterPanelSelector,
70	      ),
71	      dragHint: this._queryElement<HTMLElement>(WORK_PAGE_DOM.dragHintSelector),
72	    };
73	  }
74	
75	  readState(elements: WorksPageElements): WorksPageState {
76	    const root = elements.root;
77	    const viewRaw = root?.dataset.view;
78	    const view: WorksViewMode =
79	      viewRaw === "grid" || viewRaw === "scatter"
80	        ? viewRaw
81	        : WORK_PAGE_STATE_DEFAULT.view;
82	    const categoryRaw = root?.dataset.category?.trim() ?? "";
83	    const pageRaw = Number.parseInt(root?.dataset.page ?? "", 10);
84	    const limitRaw = Number.parseInt(root?.dataset.limit ?? "", 10);
85	
86	    return {
87	      view,
88	      category: categoryRaw.length > 0 ? categoryRaw : null,
89	      page:
90	        Number.isFinite(pageRaw) && pageRaw > 0
91	          ? pageRaw
92	          : WORK_PAGE_STATE_DEFAULT.page,
93	      limit:
94	        Number.isFinite(limitRaw) && limitRaw > 0
95	          ? limitRaw
96	          : WORK_PAGE_STATE_DEFAULT.limit,
97	    };
98	  }
99	
100	  private _queryElement<TElement extends HTMLElement>(
101	    selector: string,
102	  ): TElement | null {
103	    return this._root.querySelector<TElement>(selector);
104	  }
105	
106	  private _queryCanvasElement(canvasId: string): HTMLCanvasElement | null {
107	    return this._root.querySelector<HTMLCanvasElement>(`#${canvasId}`);
108	  }
109	}
