154	class WorksPageUiRuntime {
155	  private readonly _elements: WorksPageElements;
156	  private _gridEnterRafId: number | null = null;
157	  private _toggleRevealRafId: number | null = null;
158	  private _toggleRevealTimeoutId: number | null = null;
159	  private _dragHintTimeoutId: number | null = null;
160	  private _dragHintDeactivateTimeoutId: number | null = null;
161	  private _dragHintExitTimeoutId: number | null = null;
162	
163	  constructor(elements: WorksPageElements) {
164	    this._elements = elements;
165	  }
166	
167	  applyInitialState(state: WorksPageState): void {
168	    this.hideViewToggle();
169	    this.hideDragHint();
170	    if (state.view === "grid") {
171	      this.showGrid();
172	      return;
173	    }
174	    this.hideGrid();
