182	  enterGrid(): void {
183	    this.hideIntroIfReady();
184	    this.showGrid();
185	    this.showViewToggle();
186	    const grid = this._elements.grid;
187	    if (!grid) return;
188	    grid.classList.remove(WORK_PAGE_DOM.gridEnterClass);
189	    this._gridEnterRafId = FrameScheduler.request(() => {
190	      this._elements.grid?.classList.add(WORK_PAGE_DOM.gridEnterClass);
