194	
195	  scheduleViewToggleReveal(delayMs: number): void {
196	    if (this._toggleRevealTimeoutId !== null) {
197	      window.clearTimeout(this._toggleRevealTimeoutId);
198	      this._toggleRevealTimeoutId = null;
199	    }
200	    if (this._toggleRevealRafId !== null) {
201	      FrameScheduler.cancel(this._toggleRevealRafId);
202	      this._toggleRevealRafId = null;
203	    }
204	    this._toggleRevealTimeoutId = window.setTimeout(
205	      () => {
206	        this._toggleRevealTimeoutId = null;
207	        this._toggleRevealRafId = FrameScheduler.request(() => {
208	          this.showViewToggle();
209	          this._toggleRevealRafId = null;
210	        });
211	      },
212	      Math.max(0, delayMs),
213	    );
214	  }
215	
216	  showViewToggle(): void {
217	    const controls = this._elements.controls;
218	    if (!controls) return;
219	    this._elements.root?.setAttribute("data-ui-ready", "true");
220	    controls.hidden = false;
221	    controls.dataset.ready = "true";
222	    controls.removeAttribute("inert");
223	    Aria.setHidden(controls, false);
224	  }
225	
226	  hideViewToggle(): void {
227	    const controls = this._elements.controls;
228	    if (!controls) return;
229	    this._elements.root?.setAttribute("data-ui-ready", "false");
230	    controls.hidden = true;
231	    controls.dataset.ready = "false";
232	    controls.setAttribute("inert", "");
233	    Aria.setHidden(controls, true);
