235	
236	  showGrid(): void {
237	    this._syncViewAttributes("grid");
238	    const grid = this._elements.grid;
239	    if (!grid) return;
240	    grid.hidden = false;
241	    grid.classList.remove("is-hidden");
242	    Aria.setHidden(grid, false);
243	  }
244	
245	  hideGrid(): void {
246	    this._syncViewAttributes("scatter");
247	    const grid = this._elements.grid;
248	    if (!grid) return;
249	    grid.hidden = true;
250	    grid.classList.add("is-hidden");
251	    Aria.setHidden(grid, true);
