253	
254	  hideCanvas(): void {
255	    const canvas = this._elements.canvas;
256	    if (!canvas) return;
257	    canvas.classList.add("is-hidden");
258	    Aria.setHidden(canvas, true);
259	  }
260	
261	  showCanvas(): void {
262	    const canvas = this._elements.canvas;
263	    if (!canvas) return;
264	    canvas.classList.remove("is-hidden");
265	    Aria.setHidden(canvas, false);
266	  }
267	
268	  syncFilterSelection(
269	    category: string | null,
270	    options?: { animateLabel?: boolean },
271	  ): void {
272	    const filterButton = this._elements.filterButton;
273	    const filterPanel = this._elements.filterPanel;
274	    if (!filterButton || !filterPanel) return;
275	    const optionNodes = filterPanel.querySelectorAll<HTMLElement>(
276	      WORK_PAGE_DOM.filterOptionSelector,
277	    );
278	    let activeLabel = "전체";
279	    optionNodes.forEach((option) => {
280	      const optionCategory = option.dataset.category?.trim() ?? "";
281	      const isActive =
282	        (category === null && optionCategory.length === 0) ||
283	        optionCategory === (category ?? "");
284	      option.classList.toggle("is-active", isActive);
285	      option.setAttribute("aria-pressed", isActive ? "true" : "false");
286	      if (!isActive) return;
287	      activeLabel =
288	        option.dataset.label?.trim() || option.textContent?.trim() || "전체";
289	    });
290	    const labelElement = filterButton.querySelector<HTMLElement>(
291	      ".no-works-canvas__filter-button-label",
292	    );
293	    if (!labelElement) return;
294	    const previousLabel = labelElement.textContent ?? "";
295	    const shouldAnimate =
296	      options?.animateLabel === true && previousLabel !== activeLabel;
297	
298	    if (!shouldAnimate) {
299	      labelElement.textContent = activeLabel;
300	      return;
301	    }
302	
303	    filterButton.classList.remove("is-filter-label-entering");
304	    filterButton.classList.add("is-filter-label-leaving");
305	    window.setTimeout(() => {
306	      labelElement.textContent = activeLabel;
307	      filterButton.classList.remove("is-filter-label-leaving");
308	      filterButton.classList.add("is-filter-label-entering");
309	      window.setTimeout(() => {
310	        filterButton.classList.remove("is-filter-label-entering");
311	      }, WORKS_FILTER_TRANSITION_MS);
312	    }, WORKS_FILTER_TRANSITION_MS);
313	  }
314	
315	  syncViewLinks(category: string | null): void {
316	    const toggle = this._elements.toggle;
317	    if (!toggle) return;
318	    const links = toggle.querySelectorAll<HTMLAnchorElement>("a[href]");
319	    links.forEach((link) => {
320	      const url = new URL(link.href, window.location.origin);
321	      const view = url.searchParams.get("view") ?? "scatter";
322	      url.searchParams.set("view", view);
323	      if (category) {
324	        url.searchParams.set("category", category);
325	      } else {
326	        url.searchParams.delete("category");
327	      }
328	      link.href = `${url.pathname}${url.search}${url.hash}`;
329	    });
330	  }
331	
332	  showDragHint(): void {
333	    if (!WORK_HINT_CONFIG.enabled) return;
334	    this._clearDragHintTimers();
335	    const dragHint = this._elements.dragHint;
336	    if (!dragHint) return;
337	    dragHint.hidden = false;
338	    dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
339	    dragHint.classList.add(WORK_PAGE_DOM.dragHintVisibleClass);
340	    dragHint.removeAttribute("inert");
341	    Aria.setHidden(dragHint, false);
342	    this._dragHintTimeoutId = window.setTimeout(() => {
343	      this.hideDragHint();
344	    }, WORK_HINT_CONFIG.autoHideMs);
345	  }
346	
347	  showDragHintIfNeeded(state: WorksPageState): void {
348	    if (!WORK_HINT_CONFIG.enabled) return;
349	    if (state.view !== "scatter") return;
350	    this.showDragHint();
351	  }
352	
353	  hideDragHint(): void {
354	    this._clearDragHintTimers();
355	    const dragHint = this._elements.dragHint;
356	    if (!dragHint) return;
357	    dragHint.hidden = false;
358	    this._dragHintDeactivateTimeoutId = window.setTimeout(() => {
359	      dragHint.classList.remove(WORK_PAGE_DOM.dragHintVisibleClass);
360	      dragHint.classList.add(WORK_PAGE_DOM.dragHintHidingClass);
361	      this._dragHintDeactivateTimeoutId = null;
362	      this._dragHintExitTimeoutId = window.setTimeout(() => {
363	        dragHint.setAttribute("inert", "");
364	        Aria.setHidden(dragHint, true);
365	        dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
366	        this._dragHintExitTimeoutId = null;
367	      }, WORK_HINT_CONFIG.exitDurationMs);
368	    }, WORK_HINT_CONFIG.hideStartDelayMs);
369	  }
370	
371	  dispose(): void {
372	    if (this._gridEnterRafId !== null) {
373	      FrameScheduler.cancel(this._gridEnterRafId);
374	      this._gridEnterRafId = null;
375	    }
376	    if (this._toggleRevealRafId !== null) {
377	      FrameScheduler.cancel(this._toggleRevealRafId);
378	      this._toggleRevealRafId = null;
379	    }
380	    if (this._toggleRevealTimeoutId !== null) {
381	      window.clearTimeout(this._toggleRevealTimeoutId);
382	      this._toggleRevealTimeoutId = null;
383	    }
384	    this._clearDragHintTimers();
385	    this._resetDragHint();
386	    this._elements.grid?.classList.remove(WORK_PAGE_DOM.gridEnterClass);
387	  }
388	
389	  private _syncViewAttributes(view: WorksViewMode): void {
390	    this._elements.root?.setAttribute("data-view", view);
391	    this._elements.toggle?.setAttribute("data-view", view);
392	  }
393	
394	  private _clearDragHintTimers(): void {
395	    if (this._dragHintTimeoutId !== null) {
396	      window.clearTimeout(this._dragHintTimeoutId);
397	      this._dragHintTimeoutId = null;
398	    }
399	    if (this._dragHintExitTimeoutId !== null) {
400	      window.clearTimeout(this._dragHintExitTimeoutId);
401	      this._dragHintExitTimeoutId = null;
402	    }
403	    if (this._dragHintDeactivateTimeoutId !== null) {
404	      window.clearTimeout(this._dragHintDeactivateTimeoutId);
405	      this._dragHintDeactivateTimeoutId = null;
406	    }
407	  }
408	
409	  private _resetDragHint(): void {
410	    const dragHint = this._elements.dragHint;
411	    if (!dragHint) return;
412	    dragHint.hidden = true;
413	    dragHint.setAttribute("inert", "");
414	    dragHint.classList.remove(
415	      WORK_PAGE_DOM.dragHintVisibleClass,
416	      WORK_PAGE_DOM.dragHintHidingClass,
417	    );
418	    Aria.setHidden(dragHint, true);
419	  }
420	}
