422	class WorksGridFeedRuntime {
423	  private readonly _state: WorksPageState;
424	  private readonly _elements: WorksPageElements;
425	  private _feedState: WorksGridFeedState = {
426	    nextOffset: null,
427	    hasMore: false,
428	  };
429	  private _abortController: AbortController | null = null;
430	  private _loading = false;
431	  private _thresholdArmed = true;
432	  private _bound = false;
433	  private readonly _videoHoverCleanups: Array<() => void> = [];
434	  private _category: string | null;
435	  private _sentinel: HTMLDivElement | null = null;
436	  private _sentinelObserver: IntersectionObserver | null = null;
437	  private _filterModal: HTMLDivElement | null = null;
438	  private readonly _filterModalCleanups: Array<() => void> = [];
439	
440	  constructor(state: WorksPageState, elements: WorksPageElements) {
441	    this._state = state;
442	    this._elements = elements;
443	    this._category = state.category;
444	  }
445	
446	  async init(): Promise<void> {
447	    const list = this._elements.gridList;
448	    if (!list) return;
449	    this._clearList();
450	    this._feedState = {
451	      nextOffset: null,
452	      hasMore: false,
453	    };
454	    this._syncRootState();
455	    this._abortController?.abort();
456	    this._abortController = new AbortController();
457	    const grid = this._elements.grid;
458	    if (grid) grid.dataset.loading = "true";
459	    try {
460	      const response = await this._fetchItems(this._resolveInitialOffset());
461	      this._appendItems(response.items);
462	      this._feedState = {
463	        nextOffset: response.nextOffset,
464	        hasMore: response.hasMore,
465	      };
466	      this._syncRootState();
467	      this._syncPaginationVisibility();
468	      this._attachSentinel();
469	    } catch (error) {
470	      if (error instanceof DOMException && error.name === "AbortError") return;
471	      throw error;
472	    } finally {
473	      this._abortController = null;
474	      if (grid) delete grid.dataset.loading;
475	    }
476	  }
477	
478	  bind(): void {
479	    if (this._bound) return;
480	    window.addEventListener("scroll", this._handleScroll, { passive: true });
481	    this._bound = true;
482	    this._bindFilterModal();
483	  }
484	
485	  dispose(): void {
486	    if (this._bound) {
487	      window.removeEventListener("scroll", this._handleScroll);
488	      this._bound = false;
489	    }
490	    this._abortController?.abort();
491	    this._abortController = null;
492	    this._loading = false;
493	    this._thresholdArmed = true;
494	    this._runVideoHoverCleanups();
495	    this._detachSentinel();
496	    this._removeFilterModal();
497	  }
498	
499	  async changeCategory(category: string | null): Promise<void> {
500	    this._category = category;
501	    this._elements.root?.setAttribute("data-category", category ?? "");
502	    await this.init();
503	    this._syncFilterModalSelection(category);
504	  }
505	
506	  private readonly _handleScroll = (): void => {
507	    if (!this._feedState.hasMore) return;
508	    if (this._loading) return;
509	    const list = this._elements.gridList;
510	    if (!list) return;
511	    const thresholdReached = this._isThresholdReached(list);
512	    if (!thresholdReached) {
513	      this._thresholdArmed = true;
514	      return;
515	    }
516	    if (!this._thresholdArmed) return;
517	    this._thresholdArmed = false;
518	    void this._loadMore();
519	  };
520	
521	  private _isThresholdReached(list: HTMLElement): boolean {
522	    const rect = list.getBoundingClientRect();
523	    return (
524	      rect.bottom - window.innerHeight <= WORK_GRID_INFINITE_CONFIG.thresholdPx
525	    );
526	  }
527	
528	  private _attachSentinel(): void {
529	    this._detachSentinel();
530	    if (!this._feedState.hasMore) return;
531	    const list = this._elements.gridList;
532	    if (!list) return;
533	    const sentinel = document.createElement("div");
534	    sentinel.style.height = "1px";
535	    sentinel.setAttribute("aria-hidden", "true");
536	    list.after(sentinel);
537	    this._sentinel = sentinel;
538	    this._sentinelObserver = new IntersectionObserver(
539	      (entries) => {
540	        if (entries[0]?.isIntersecting) void this._loadMore();
541	      },
542	      { rootMargin: `${WORK_GRID_INFINITE_CONFIG.thresholdPx}px` },
543	    );
544	    this._sentinelObserver.observe(sentinel);
545	  }
546	
547	  private _detachSentinel(): void {
548	    this._sentinelObserver?.disconnect();
549	    this._sentinelObserver = null;
550	    this._sentinel?.remove();
551	    this._sentinel = null;
552	  }
553	
554	  private _bindFilterModal(): void {
555	    const filterPanel = this._elements.filterPanel;
556	    if (!filterPanel) return;
557	    const trigger = this._elements.root?.querySelector<HTMLButtonElement>(
558	      ".js-grid-filter-trigger",
559	    );
560	    if (!trigger) return;
561	
562	    const categories: Array<{ slug: string; label: string }> = [];
563	    filterPanel
564	      .querySelectorAll<HTMLElement>("[data-works-filter-option]")
565	      .forEach((el) => {
566	        categories.push({
567	          slug: el.dataset.category ?? "",
568	          label: el.dataset.label ?? el.textContent?.trim() ?? "",
569	        });
570	      });
571	    if (categories.length === 0) return;
572	
573	    const modal = document.createElement("div");
574	    modal.className = "no-grid-filter-modal";
575	    modal.setAttribute("aria-hidden", "true");
576	    modal.setAttribute("role", "dialog");
577	    modal.setAttribute("aria-label", "카테고리 필터");
578	
579	    const backdrop = document.createElement("div");
580	    backdrop.className = "no-grid-filter-modal__backdrop";
581	
582	    const sheet = document.createElement("div");
583	    sheet.className = "no-grid-filter-modal__sheet";
584	
585	    const header = document.createElement("div");
586	    header.className = "no-grid-filter-modal__header";
587	    const headerTitle = document.createElement("span");
588	    headerTitle.textContent = "Category";
589	    const closeBtn = document.createElement("button");
590	    closeBtn.type = "button";
591	    closeBtn.className = "no-grid-filter-modal__close";
592	    closeBtn.setAttribute("aria-label", "닫기");
593	    closeBtn.textContent = "✕";
594	    header.append(headerTitle, closeBtn);
595	
596	    const list = document.createElement("ul");
597	    list.className = "no-grid-filter-modal__list";
598	    categories.forEach(({ slug, label }) => {
599	      const li = document.createElement("li");
600	      const btn = document.createElement("button");
601	      btn.type = "button";
602	      btn.className = "no-grid-filter-modal__option";
603	      btn.dataset.category = slug;
604	      btn.textContent = label;
605	      li.append(btn);
606	      list.append(li);
607	    });
608	
609	    sheet.append(header, list);
610	    modal.append(backdrop, sheet);
611	    document.body.append(modal);
612	    this._filterModal = modal;
613	    this._syncFilterModalSelection(this._category);
614	
615	    const openModal = (): void => {
616	      modal.setAttribute("aria-hidden", "false");
617	      modal.classList.add("is-open");
618	      document.body.classList.add("no-scroll");
619	    };
620	    const closeModal = (): void => {
621	      modal.setAttribute("aria-hidden", "true");
622	      modal.classList.remove("is-open");
623	      document.body.classList.remove("no-scroll");
624	    };
625	    const onOptionClick = (event: MouseEvent): void => {
626	      const btn = (event.target as HTMLElement).closest<HTMLButtonElement>(
627	        "[data-category]",
628	      );
629	      if (!btn) return;
