219	
220	  constructor(
221	    layout: WorkLayoutConstants,
222	    camPadX: number,
223	    camPadY: number,
224	    camZ: number,
225	  ) {
226	    this._layout = layout;
227	    this._camPadX = camPadX;
228	    this._camPadY = camPadY;
229	    this._baseCamZ = camZ;
230	    this._targetZ = camZ;
231	    this._dynClampMinX = -camPadX;
