237	  setDynamicClamp(positions: ReadonlyArray<WorksScatterPosition>): void {
238	    if (positions.length === 0) {
239	      this._dynClampMinX = this._dynClampMaxX = 0;
240	      this._dynClampMinY = this._dynClampMaxY = 0;
241	      return;
242	    }
243	    const MARGIN = 8;
244	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
245	    for (const p of positions) {
246	      if (p.x < minX) minX = p.x;
247	      if (p.x > maxX) maxX = p.x;
248	      if (p.y < minY) minY = p.y;
249	      if (p.y > maxY) maxY = p.y;
250	    }
251	    this._dynClampMinX = minX - MARGIN;
252	    this._dynClampMaxX = maxX + MARGIN;
253	    this._dynClampMinY = minY - MARGIN;
254	    this._dynClampMaxY = maxY + MARGIN;
255	  }
