291	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
292	    this._isDragging = true;
293	    this._dragPrevious = { ...pointer };
294	    this._velocityX = 0;
295	    this._velocityY = 0;
296	    this._targetX = camera.position.x;
297	    this._targetY = camera.position.y;
