328	  updateFrame(camera: THREE.Camera, delta: number): void {
329	    if (this._isDragging) {
330	      const decay = Math.pow(this._layout.velDecay, delta * 60);
331	      this._velocityX *= decay;
332	      this._velocityY *= decay;
333	      this._targetX += this._velocityX * delta * 60;
334	      this._targetY += this._velocityY * delta * 60;
335	    }
336	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
337	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
338	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
339	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
340	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
341	    camera.lookAt(camera.position.x, camera.position.y, 0);
342	  }
