627	  update(delta: number): void {
628	    if (!this.camera || !this.scene) return;
629	    const camera = this.camera;
630	    this.cameraMotionRuntime.updateFrame(camera, delta);
631	
632	    // Hover video: activate / deactivate when hovered mesh changes
633	    if (this.hovered !== this._prevHovered) {
634	      if (this._prevHovered) this._hoverVideo.deactivate();
635	      if (this.hovered) {
636	        const userData = this.hovered.userData as WorkCardUserData;
637	        if (userData.proj.thumbnailVideo) {
638	          const material = this.hovered.material as THREE.MeshBasicMaterial;
639	          const texture = material.map;
640	          if (texture instanceof THREE.CanvasTexture) {
641	            this._hoverVideo.activate(
642	              this.hovered,
643	              texture,
644	              userData.proj.thumbnailVideo,
645	              userData.proj,
646	              this._cardSize,
647	              userData.loadedImage ?? null,
648	            );
649	          }
650	        }
651	      }
652	      this._prevHovered = this.hovered;
653	    }
654	    if (this._hoverVideo.isActive()) this._hoverVideo.drawFrame();
655	
656	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
657	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
658	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
659	    const isGridView = this.viewMode === "grid";
660	    const hover =
661	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
662	    const blendT =
663	      this._filterBlendStartMs > 0
664	        ? Math.min(
665	            1,
666	            (performance.now() - this._filterBlendStartMs) /
667	              WorksSceneManager._filterBlendMs,
668	          )
669	        : 1;
670	    const filterEase = 1 - Math.pow(1 - blendT, 3);
671	    for (let index = 0; index < this.meshes.length; index += 1) {
672	      const mesh = this.meshes[index];
673	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
674	      const isActiveCategory = this.isMeshInCategory(mesh);
675	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
676	      const nowIn = isActiveCategory;
677	      let targetY = target.y;
678	      if (wasIn && !nowIn && blendT < 1) {
679	        targetY += (1 - filterEase) * 6.5;
680	      }
681	      if (!wasIn && nowIn && blendT < 1) {
682	        targetY -= (1 - filterEase) * 7.5;
683	      }
684	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
685	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
686	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
687	      mesh.quaternion.copy(camera.quaternion);
688	      const opacityAnchor = isActiveCategory ? target : mesh.position;
689	      const distance = dist2d(
690	        camera.position.x,
691	        camera.position.y,
692	        opacityAnchor.x,
693	        opacityAnchor.y,
694	      );
695	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
696	      if (!isActiveCategory) targetOpacity = 0;
697	      if (isActiveCategory && this.activeCategory !== null) {
698	        targetOpacity = Math.max(0.3, targetOpacity);
699	      }
700	      if (isGridView) targetOpacity = 0;
701	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
702	      if (nowIn && !wasIn) {
703	        targetOpacity *= filterEase;
704	      }
705	      const material = mesh.material as THREE.MeshBasicMaterial;
706	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
707	      const steadyScale = (hover === mesh ? 1.06 : 1) * this._cardScale;
708	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
709	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
710	    }
711	  }
