796	        if (this.activePointerId === null) {
797	          this.hovered = this.hitRuntime.resolve(
798	            this.camera,
799	            viewport,
800	            { x: event.clientX, y: event.clientY },
801	            this.interactiveMeshes,
802	          );
803	        }
804	        return;
805	      }
806	      if (this.cameraMotionRuntime.isDragging) {
807	        if (
808	          !this.dragInteractionStarted &&
809	          Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) >=
