854	        this.viewMode === "scatter" &&
855	        this.mouseDownMesh &&
856	        this.isMeshInCategory(this.mouseDownMesh) &&
857	        Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) <
