878	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
879	        const halfWidth = halfHeight * (viewport.width / viewport.height);
880	        this.camera.left = -halfWidth;
881	        this.camera.right = halfWidth;
882	        this.camera.top = halfHeight;
883	        this.camera.bottom = -halfHeight;
884	        this.camera.updateProjectionMatrix();
885	      }
886	      this.renderer.setPixelRatio(viewport.dpr);
887	      this.renderer.setSize(viewport.width, viewport.height);
888	      this._cardScale = Math.min(1, viewport.width / CARD_SCALE_BASE_WIDTH);
889	    };
