891	    canvas.addEventListener("pointerdown", onPointerDown);
892	    canvas.addEventListener("pointerup", onPointerUp);
893	    canvas.addEventListener("pointercancel", onPointerCancel);
894	    canvas.addEventListener("pointerleave", onPointerLeave);
