912	      if (!this.camera || !this.renderer || !this.scene || !this.clock) {
913	        this.rafId = null;
914	        return;
915	      }
916	      this.rafId = FrameScheduler.request(animate);
917	      const delta = Math.min(this.clock.getDelta(), MAX_DELTA_SECONDS);
918	      this.update(delta);
919	      this.renderer.render(this.scene, this.camera);
920	    };
921	    animate();
922	  }
