955	  private _centerCameraOnVisiblePositions(
956	    positions: ReadonlyArray<WorksScatterPosition>,
957	  ): void {
958	    const center = this._readVisiblePositionsCenter(positions);
959	    this.cameraMotionRuntime.setTargetPosition(center.x, center.y);
