961	
962	  private _readVisiblePositionsCenter(
963	    positions: ReadonlyArray<WorksScatterPosition>,
964	  ): WorksScatterPosition {
965	    if (positions.length === 0) {
966	      return { x: 0, y: 0 };
967	    }
968	    let minX = positions[0]?.x ?? 0;
969	    let maxX = minX;
970	    let minY = positions[0]?.y ?? 0;
971	    let maxY = minY;
972	    for (let index = 1; index < positions.length; index += 1) {
973	      const position = positions[index];
974	      if (!position) continue;
975	      minX = Math.min(minX, position.x);
976	      maxX = Math.max(maxX, position.x);
977	      minY = Math.min(minY, position.y);
978	      maxY = Math.max(maxY, position.y);
979	    }
980	    return {
981	      x: (minX + maxX) * 0.5,
982	      y: (minY + maxY) * 0.5,
983	    };
984	  }
